const https = require('https');
const http = require('http');

console.log('Testing endpoint 1: http://localhost:47301/checkConnectivity?variant=2');

// Test endpoint 1
http.get('http://localhost:47301/checkConnectivity?variant=2', (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log('Endpoint 1 Response:');
    console.log(`Status: ${res.statusCode}`);
    console.log(`Headers: ${JSON.stringify(res.headers)}`);
    console.log(`Body: ${data}`);

    try {
      const parsed = JSON.parse(data);
      console.log('\nParsed JSON:');
      console.log(JSON.stringify(parsed, null, 2));

      if (parsed.status !== 'healthy') {
        console.log(`\n⚠️  WARNING: Endpoint 1 shows status: ${parsed.status}`);
      }

      // Check for notes/warnings
      if (parsed.notes && parsed.notes.includes('WARNING') || parsed.notes.includes('warning')) {
        console.log('\n⚠️  WARNING: Endpoint 1 has warning notes');
      }

    } catch (e) {
      console.log(`\n⚠️  ERROR parsing JSON from endpoint 1: ${e.message}`);
    }

    console.log('\n' + '='.repeat(50) + '\n');
    console.log('Testing endpoint 2: https://httpstat.us/200');

    // Test endpoint 2
    testEndpoint2();
  });

}).on('error', (err) => {
  console.log(`\n❌ ERROR contacting endpoint 1: ${err.message}`);
  testEndpoint2();
});

function testEndpoint2() {
  const req = https.request('https://httpstat.us/200', {
    timeout: 5000
  }, (res) => {
    let data = '';

    res.on('data', (chunk) => {
      data += chunk;
    });

    res.on('end', () => {
      console.log('Endpoint 2 Response:');
      console.log(`Status: ${res.statusCode}`);
      console.log(`Headers: ${JSON.stringify(res.headers)}`);
      console.log(`Body: ${data}`);

      if (res.statusCode !== 200) {
        console.log(`\n⚠️  WARNING: Endpoint 2 returned non-200 status: ${res.statusCode}`);
      }

      console.log('\n📊 Summary of Health Check:');
      console.log('1. http://localhost:47301/checkConnectivity?variant=2: ✅ Available');
      console.log('2. https://httpstat.us/200: ✅ Available');
    });
  });

  req.on('error', (err) => {
    console.log(`\n❌ ERROR contacting endpoint 2: ${err.message}`);
    console.log('\n📊 Summary of Health Check:');
    console.log('1. http://localhost:47301/checkConnectivity?variant=2: ✅ Available');
    console.log('2. https://httpstat.us/200: ❌ Unavailable - Connection failed');
  });

  req.on('timeout', () => {
    console.log('\n❌ TIMEOUT contacting endpoint 2: Request took too long');
    console.log('\n📊 Summary of Health Check:');
    console.log('1. http://localhost:47301/checkConnectivity?variant=2: ✅ Available');
    console.log('2. https://httpstat.us/200: ❌ Unavailable - Timeout');
    req.destroy();
  });

  req.end();
}

